// app/Sources/GraphicStore+Import.swift — a font or a picture copied into
// `graphics/fonts/` or `graphics/assets/` (road map 10 §5h, G4b; G5b): the
// ONE body behind the agent's `import_graphic_font` and
// `import_graphic_asset` and a person's File ▸ Add Font to Graphics… and
// Add Image to Graphics…, so the two doors refuse in the same sentences.
//
// It goes through `ensureFolder()`, the ONE creator of `graphics/` inside a
// package (G-14), and lands the file the way `write(name:source:)` lands a
// module: a `<name>.partial` beside it, then moved into place, so the scan
// never reads half a file (a `.partial`'s extension is in neither the font
// nor the asset set, so it is never listed). `importFile` does not rescan;
// `importFont` and `importAsset` end in ONE `rescan()`, so the registry has
// its new library when they return — both are called from a handler or a
// command, never from a `.graphicsDidChange` observer (`drain()` is not
// re-entrant).
//
// **A font's family names are the ENGINE's own** (`rc_graphic_library_families`):
// the file is loaded into a throwaway library of its own and that library is
// asked, so `families` is exactly what a `font-family` must say — CoreText
// names some files differently (road map 10 §10.7 G4b measured 13 of 2500).
// Not undoable and never dirty (G-3).
//
// **An asset's name is one `asset(name)` can use** (spec §11 G-23): a name
// that is not is legalised (`GraphicAssetName`) and the copy filed under it,
// taking `-2`, `-3`, … while that name is held (scan or disk), so a RENAMED
// copy never replaces; the answer says the name used and the name asked for.

import Foundation

extension GraphicStore {
    /// Copies `source` to `graphics/<subfolder>/<name>`, replacing a file of
    /// that name. Whether one was replaced. Main.
    func importFile(from source: URL, into subfolder: String, as name: String) throws
        -> (url: URL, replaced: Bool)
    {
        try ensureFolder()
        let files = FileManager.default
        let folder = folderURL.appendingPathComponent(subfolder, isDirectory: true)
        try files.createDirectory(at: folder, withIntermediateDirectories: true)
        let target = folder.appendingPathComponent(name)
        let replaced = try Self.land(at: target) { try files.copyItem(at: source, to: $0) }
        return (target, replaced)
    }

    /// What `graphics/assets/` takes, in the refusals' words.
    static let assetKinds = "PNG, JPEG, GIF, WebP, SVG or SVGZ"

    /// A `.ttf` or `.otf` copied into `graphics/fonts/` under its own name,
    /// then `rescan()`. The families are the engine's reading of that file
    /// alone. Main.
    func importFont(from source: URL) throws -> (url: URL, replaced: Bool, families: [String]) {
        let path = source.path
        guard Self.fontExtensions.contains(source.pathExtension.lowercased()) else {
            throw ReelCoreError(message: "\(path) is not a .ttf or .otf file")
        }
        let bytes: Data
        do {
            bytes = try Data(contentsOf: source)
        } catch {
            throw ReelCoreError(
                message: "\(path) could not be read: \(error.localizedDescription)")
        }
        let probe = GraphicLibrary()
        do {
            try probe.addFont(bytes)
        } catch let error as ReelCoreError {
            throw ReelCoreError(message: "\(path): " + error.message)
        }
        let families = probe.families()
        let landed = try importNamed(source, Self.fontsFolderName, source.lastPathComponent)
        rescan()
        return (landed.url, landed.replaced, families)
    }

    /// A picture copied into `graphics/assets/<name>`, then `rescan()`.
    /// `name` is what `asset(name)` says; its extension must be one of the
    /// six. A name `asset(name)` cannot use is filed under a legal one
    /// (`renamedFrom` is the name asked for), never replacing a file. Main.
    func importAsset(from source: URL, as name: String) throws
        -> (url: URL, name: String, replaced: Bool, bytes: Int, renamedFrom: String?)
    {
        let path = source.path
        let kinds = Self.assetKinds
        guard !name.isEmpty, !name.contains("/") else {
            throw ReelCoreError(
                message: "name must be a file name with no / (got \"\(name)\") — it is what "
                    + "asset(name) says")
        }
        guard Self.assetExtensions.contains((name as NSString).pathExtension.lowercased())
        else {
            throw ReelCoreError(
                message: "\(name) is not a \(kinds) file (.png .jpg .jpeg .gif .webp .svg .svgz)")
        }
        let size = (try? FileManager.default.attributesOfItem(atPath: source.path)[.size]
            as? NSNumber)?.intValue ?? 0
        // An empty file crosses the FFI as NULL and the scan skips it.
        guard size > 0 else {
            throw ReelCoreError(
                message: "\(path) is empty (0 bytes) — an asset must hold a \(kinds) image")
        }
        let legal = GraphicAssetName.legalized(name)
        var used = legal
        if legal != name {
            var n = 2
            while holdsAsset(named: used) {
                used = GraphicAssetName.withSuffix(legal, n)
                n += 1
            }
        }
        let landed = try importNamed(source, Self.assetsFolderName, used)
        rescan()
        return (landed.url, used, landed.replaced, size, used == name ? nil : name)
    }

    /// True when the scan lists `name` or `graphics/assets/<name>` is on disk.
    func holdsAsset(named name: String) -> Bool {
        scan.assets.contains { $0.name == name }
            || FileManager.default.fileExists(
                atPath: folderURL.appendingPathComponent(Self.assetsFolderName, isDirectory: true)
                    .appendingPathComponent(name).path)
    }

    /// `importFile`, its failure said in a sentence naming the folder.
    private func importNamed(_ source: URL, _ subfolder: String, _ name: String) throws
        -> (url: URL, replaced: Bool)
    {
        do {
            return try importFile(from: source, into: subfolder, as: name)
        } catch {
            throw ReelCoreError(
                message: "graphics/\(subfolder)/\(name) could not be written: "
                    + error.localizedDescription)
        }
    }
}
// app/Sources/AgentServer+GraphicImports.swift — `import_graphic_font` and
// `import_graphic_asset` (road map 10 §5h, G4b): a file copied into the
// package's `graphics/fonts/` or `graphics/assets/` through the store's
// `importFont(from:)` / `importAsset(from:as:)` (`GraphicStore+Import.swift`),
// the SAME body File ▸ Add Font to Graphics… and Add Image to Graphics… run
// (G5b). The store ends in ONE synchronous `rescan()`, whose post reaches the
// registry even in a folder holding no module, so the library is rebuilt
// before the reply is built.
//
// Both run on MAIN: the copy is one small file, and `rescan()` must be
// called from main, from the handler — never from a `.graphicsDidChange`
// observer, because `drain()` is not re-entrant. Not undoable and never
// dirty (G-3), `write_graphic`'s posture. An asset name `asset(name)` cannot
// use is filed under a legal one (spec §11 G-23): `name` answers the name
// used, and `renamed_from` the name asked for, only when the two differ.

import Foundation

extension AgentServer {

    /// `import_graphic_font` — UI path: File ▸ Add Font to Graphics…
    /// (`EditorViewController+GraphicMenus.swift`).
    func importGraphicFont(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let store = try graphicStore(document)
        let source = try graphicImportSource(a)
        let landed = try store.importFont(from: source)
        return try jsonResult([
            "path": landed.url.path, "name": source.lastPathComponent, "replaced": landed.replaced,
            "families": landed.families, "library_families": libraryFamilies(document),
            "note": Self.notUndoableNote,
        ])
    }

    /// `import_graphic_asset` — UI path: File ▸ Add Image to Graphics…
    /// (`EditorViewController+GraphicMenus.swift`).
    func importGraphicAsset(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let store = try graphicStore(document)
        let source = try graphicImportSource(a)
        let name = try stringArg(a, "name") ?? source.lastPathComponent
        let landed = try store.importAsset(from: source, as: name)
        var result: [String: Any] = [
            "path": landed.url.path, "name": landed.name, "replaced": landed.replaced,
            "bytes": landed.bytes, "assets": store.scan.assets.map(\.name),
            "note": Self.notUndoableNote,
        ]
        if let asked = landed.renamedFrom { result["renamed_from"] = asked }
        return try jsonResult(result)
    }

    /// `path`, `~` expanded: a regular file, or the sentence saying there is none.
    private func graphicImportSource(_ a: [String: Any]) throws -> URL {
        let path = (try requiredString(a, "path") as NSString).expandingTildeInPath
        var isDirectory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: path, isDirectory: &isDirectory),
            !isDirectory.boolValue
        else { throw ToolError(message: "No file at \(path).") }
        return URL(fileURLWithPath: path)
    }
}
